// Runtime measurements remain on this device; no visitor data is transmitted.
export function createPerformanceMonitor(renderer){
 const capacity=180,periods=new Float32Array(capacity),cpu=new Float32Array(capacity),draws=new Float32Array(capacity),tris=new Float32Array(capacity),phases={};
 const gl=renderer.getContext(),ext=gl.getExtension('EXT_disjoint_timer_query_webgl2'),pending=[];let active=null,count=0,cursor=0,start=0,phase='frame',longTasks=0,longTaskMs=0,interactiveStart=Infinity;
 renderer.info.autoReset=false;
 try{if(globalThis.PerformanceObserver?.supportedEntryTypes?.includes('longtask'))new PerformanceObserver(list=>{for(const e of list.getEntries())if(e.startTime>=interactiveStart){longTasks++;longTaskMs+=e.duration;}}).observe({type:'longtask',buffered:true});}catch{}
 function poll(){if(!ext)return;const disjoint=gl.getParameter(ext.GPU_DISJOINT_EXT);for(let i=pending.length-1;i>=0;i--){const p=pending[i];if(!gl.getQueryParameter(p.query,gl.QUERY_RESULT_AVAILABLE))continue;if(!disjoint){const ms=gl.getQueryParameter(p.query,gl.QUERY_RESULT)/1e6,s=phases[p.name]||={samples:0,cpuMs:0,gpuMs:null};s.gpuMs=s.gpuMs===null?ms:s.gpuMs*.85+ms*.15;}gl.deleteQuery(p.query);pending.splice(i,1);}}
 function beginGpu(name){if(!ext||active||pending.length>=4||phase!==name)return false;const query=gl.createQuery();gl.beginQuery(ext.TIME_ELAPSED_EXT,query);active={name,query};return true;}
 function endGpu(){if(!active)return;gl.endQuery(ext.TIME_ELAPSED_EXT);pending.push(active);active=null;}
 function measure(name,operation){const t=performance.now(),gpu=beginGpu(name);try{return operation();}finally{if(gpu)endGpu();const ms=performance.now()-t,s=phases[name]||={samples:0,cpuMs:0,gpuMs:null};s.samples++;s.cpuMs=s.samples===1?ms:s.cpuMs*.9+ms*.1;}}
 const shadow=renderer.shadowMap.render;renderer.shadowMap.render=function(...args){if(!this.enabled||!this.autoUpdate&&!this.needsUpdate)return shadow.apply(this,args);return measure('shadows',()=>shadow.apply(this,args));};
 function summary(){const n=Math.min(count,capacity);let frame=0,work=0,calls=0,triangles=0;for(let i=0;i<n;i++){frame+=periods[i];work+=cpu[i];calls+=draws[i];triangles+=tris[i];}return {frames:n,fps:n?Math.round(1000*n/frame):null,meanFrameMs:n?+(frame/n).toFixed(2):null,meanCpuFrameMs:n?+(work/n).toFixed(2):null,meanDrawCalls:n?Math.round(calls/n):null,meanRenderedTriangles:n?Math.round(triangles/n):null,phases:JSON.parse(JSON.stringify(phases)),gpuTimingAvailable:!!ext,longTasks,longTaskMilliseconds:Math.round(longTaskMs),jsHeapBytes:performance.memory?.usedJSHeapSize??null,gcTimingAvailable:false};}
 return {measure,summary,begin(now,period){if(count===0)interactiveStart=now;poll();renderer.info.reset();start=performance.now();periods[cursor]=period;const names=['frame','poolReflection','postprocessing','shadows'];phase=count%60===0?names[Math.floor(count/60)%names.length]:'none';beginGpu('frame');},end(){if(active)endGpu();cpu[cursor]=performance.now()-start;draws[cursor]=renderer.info.render.calls;tris[cursor]=renderer.info.render.triangles;cursor=(cursor+1)%capacity;count++;}};
}
